import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.CXvqQpa-.js";const k=JSON.parse('{"title":"疑難排解與常見問題","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/troubleshooting.md","filePath":"zh-TW/guide/troubleshooting.md","lastUpdated":null}'),t={name:"zh-TW/guide/troubleshooting.md"};function l(h,s,d,r,o,p){return a(),e("div",null,[...s[0]||(s[0]=[n('<h1 id="疑難排解與常見問題" tabindex="-1">疑難排解與常見問題 <a class="header-anchor" href="#疑難排解與常見問題" aria-label="Permalink to &quot;疑難排解與常見問題&quot;">​</a></h1><p>整理最常見的建置、執行階段與版本升級問題解法。</p><h2 id="事件沒有傳遞到子元件" tabindex="-1">事件沒有傳遞到子元件 <a class="header-anchor" href="#事件沒有傳遞到子元件" aria-label="Permalink to &quot;事件沒有傳遞到子元件&quot;">​</a></h2><p><strong>現象</strong>：按鈕、輸入框或選單有正確顯示在畫面上，但鍵盤或滑鼠操作毫無反應。</p><p><strong>原因</strong>：你使用了 <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/component#renderer" class="code-ref">Renderer</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> child-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/dom#render" class="code-ref">Render</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); })</span></code>，卻忘記把 <code>child</code>（或包含所有子元件的 <code>Container</code>）當作第一個參數傳入。</p><p><strong>解法</strong>：務必將 <code>Container</code> 與 <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/component#renderer" class="code-ref">Renderer</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(container, ...)</span></code> 配對使用：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> container </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/component#vertical" class="code-ref">Vertical</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({input, button});</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ui </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> <a href="/FTXUI/api/component#renderer" class="code-ref">Renderer</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(container, [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> <a href="/FTXUI/api/dom#vbox" class="code-ref">vbox</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({input-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/dom#render" class="code-ref">Render</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), button-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/dom#render" class="code-ref">Render</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()})</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">         |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> <a href="/FTXUI/api/dom#border" class="code-ref">border</a>;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>詳情請參閱<a href="/FTXUI/zh-TW/guide/mental-model">心智模型</a>指南。</p><hr><h2 id="手動連結時出現未定義參考-undefined-references" tabindex="-1">手動連結時出現未定義參考（Undefined References） <a class="header-anchor" href="#手動連結時出現未定義參考-undefined-references" aria-label="Permalink to &quot;手動連結時出現未定義參考（Undefined References）&quot;">​</a></h2><p><strong>現象</strong>：連結器報錯，提示找不到 <a href="/FTXUI/api/class/node"><code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ftxui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::Node</span></code></a>、<a href="/FTXUI/api/class/screen"><code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ftxui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::Screen</span></code></a> 或 <a href="/FTXUI/api/component#element"><code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ftxui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::Element</span></code></a>。</p><p><strong>解法</strong>：使用靜態函式庫時，連結順序非常重要（<code>component</code> 相依於 <code>dom</code>，<code>dom</code> 又相依於 <code>screen</code>）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lftxui-component</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lftxui-dom</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lftxui-screen</span></span></code></pre></div><p>若使用 CMake，直接連結 <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ftxui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::ftxui</span></code>（或 <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ftxui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::component</span></code>，它會自動帶入 <code>dom</code> 與 <code>screen</code>）即可。</p><hr><h2 id="在-linux-上以-mingw-交叉編譯-mutex-is-not-a-member-of-std" tabindex="-1">在 Linux 上以 MinGW 交叉編譯（<code>&#39;mutex&#39; is not a member of &#39;std&#39;</code>） <a class="header-anchor" href="#在-linux-上以-mingw-交叉編譯-mutex-is-not-a-member-of-std" aria-label="Permalink to &quot;在 Linux 上以 MinGW 交叉編譯（`&#39;mutex&#39; is not a member of &#39;std&#39;`）&quot;">​</a></h2><p><strong>現象</strong>：在 Debian/Ubuntu 上使用 <code>x86_64-w64-mingw32-g++</code> 編譯時失敗，出現 <code>error: &#39;mutex&#39; is not a member of &#39;std&#39;</code>。</p><p><strong>解法</strong>：Debian/Ubuntu 預設的 MinGW 編譯器採用 <code>win32</code> 執行緒模型，並未實作 C++11 的 <code>&lt;mutex&gt;</code> 與 <code>&lt;thread&gt;</code>。請切換為 <code>posix</code> 版本：</p><ul><li>在你的 CMake toolchain 檔案中，將 <code>CMAKE_CXX_COMPILER</code> 設為 <code>x86_64-w64-mingw32-g++-posix</code>，或是</li><li>執行 <code>sudo update-alternatives --config x86_64-w64-mingw32-g++</code> 並選擇 <code>x86_64-w64-mingw32-g++-posix</code>。</li></ul><hr><h2 id="windows-巨集名稱衝突-rgb、drawtext、min、max" tabindex="-1">Windows 巨集名稱衝突（<code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/api/class/color#rgb" class="code-ref">RGB</a></span></code>、<code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/api/class/canvas#drawtext" class="code-ref">DrawText</a></span></code>、<code>min</code>、<code>max</code>） <a class="header-anchor" href="#windows-巨集名稱衝突-rgb、drawtext、min、max" aria-label="Permalink to &quot;Windows 巨集名稱衝突（`RGB`、`DrawText`、`min`、`max`）&quot;">​</a></h2><p><strong>現象</strong>：引入 <code>&lt;windows.h&gt;</code> 後，在 <code>&lt;ftxui/screen/color.hpp&gt;</code> 或 <code>&lt;ftxui/dom/canvas.hpp&gt;</code> 出現奇怪的編譯錯誤。</p><p><strong>解法</strong>：在引入 <code>&lt;windows.h&gt;</code> 之前定義 <code>NOMINMAX</code> 與 <code>WIN32_LEAN_AND_MEAN</code>（或在 CMake 中加上 <code>-DNOMINMAX</code>）。FTXUI 在自身標頭檔內已經取消定義 <code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/api/class/color#rgb" class="code-ref">RGB</a></span></code> 與 <code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/api/class/canvas#drawtext" class="code-ref">DrawText</a></span></code>，但定義 <code>NOMINMAX</code> 可以避免與 <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::min</span></code>/<code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::max</span></code> 衝突。</p><hr><h2 id="終端機中的色彩、unicode-或滑鼠無法正常運作" tabindex="-1">終端機中的色彩、Unicode 或滑鼠無法正常運作 <a class="header-anchor" href="#終端機中的色彩、unicode-或滑鼠無法正常運作" aria-label="Permalink to &quot;終端機中的色彩、Unicode 或滑鼠無法正常運作&quot;">​</a></h2><ul><li><strong>手動指定色彩支援等級</strong>：<div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Terminal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/screen#setcolorsupport" class="code-ref">SetColorSupport</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Terminal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/class/color" class="code-ref">Color</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::TrueColor);</span></span></code></pre></div></li><li><strong>停用 Unicode 方塊字元，改用 ASCII 替代字元</strong>：<div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> quirks </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Terminal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/screen#getquirks" class="code-ref">GetQuirks</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">quirks.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/class/terminal-quirks#setcomponentascii" class="code-ref">SetComponentAscii</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Terminal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/screen#setquirks" class="code-ref">SetQuirks</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(quirks);</span></span></code></pre></div></li><li><strong>Windows 7 與舊版主控台</strong>：舊版 Windows <code>conhost</code>（Windows 10 之前）不支援虛擬終端機跳脫序列（<code>ENABLE_VIRTUAL_TERMINAL_PROCESSING</code>）。請改用 Windows Terminal 或其他現代的 VT100 相容終端機。</li></ul><hr><h2 id="從-ftxui-v6-升級至-v7" tabindex="-1">從 FTXUI v6 升級至 v7 <a class="header-anchor" href="#從-ftxui-v6-升級至-v7" aria-label="Permalink to &quot;從 FTXUI v6 升級至 v7&quot;">​</a></h2><p>FTXUI v7 為了語意更清晰，重新命名了三個核心類別（為了向後相容，舊名稱仍以棄用別名保留）：</p><table tabindex="0"><thead><tr><th>FTXUI v6（已棄用）</th><th>FTXUI v7</th><th>標頭檔</th></tr></thead><tbody><tr><td><code>ScreenInteractive</code></td><td><code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/api/class/app" class="code-ref">App</a></span></code></td><td><code>&lt;ftxui/component/app.hpp&gt;</code></td></tr><tr><td><code>Pixel</code> / <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/class/surface#pixelat" class="code-ref">PixelAt</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></code></td><td><code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/api/class/cell" class="code-ref">Cell</a></span></code> / <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/class/surface#cellat" class="code-ref">CellAt</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></code></td><td><code>&lt;ftxui/screen/cell.hpp&gt;</code></td></tr><tr><td><code>Image</code> / <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/class/canvas#drawimage" class="code-ref">DrawImage</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></code></td><td><code class="shiki-inline"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"><a href="/FTXUI/api/class/surface" class="code-ref">Surface</a></span></code> / <code class="shiki-inline"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"><a href="/FTXUI/api/class/canvas#drawsurface" class="code-ref">DrawSurface</a></span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></code></td><td><code>&lt;ftxui/screen/surface.hpp&gt;</code></td></tr></tbody></table>',30)])])}const E=i(t,[["render",l]]);export{k as __pageData,E as default};
